INSERT INTO city_pages (slug, name, state_code, state_name, county, zip, population, median_price, price_trend, avg_dom, description, neighborhoods, nearby, seller_hook, realtor_hook, is_published) VALUES
('park-city', 'Park City', 'UT', 'Utah', 'Summit County', '84060', '8,606', '$2,100,000', 'up 4%', 22, 'Park City is Utah''s premier ski resort destination and one of America''s most prestigious small-town real estate markets, where Deer Valley and Park City Mountain draw wealthy buyers from California, Texas, and New York seeking mountain lifestyle alongside world-class amenities.', 'Old Town, Deer Valley, Park Meadows, Promontory, Glenwild, Jeremy Ranch', 'Heber City, Kimball Junction, Salt Lake City', 'Park City luxury listings attract buyers from the world''s wealthiest markets — California tech executives, Texas energy money, and New York finance all compete for Deer Valley and Old Town properties. Sell with the agent who serves them.', 'Win Park City listings before Sotheby''s or Christie''s reaches the seller — wealthy buyers from California, Texas, and New York are always searching Deer Valley and our platform connects you to motivated sellers first.', true)
INSERT INTO city_pages (slug, name, state_code, state_name, county, zip, population, median_price, price_trend, avg_dom, description, neighborhoods, nearby, seller_hook, realtor_hook, is_published) VALUES
('charleston', 'Charleston', 'SC', 'South Carolina', 'Charleston County', '29401', '150,227', '$595,000', 'up 6%', 17, 'Charleston is one of America''s most desirable cities, where a UNESCO-worthy historic district, world-class culinary scene, and Atlantic Ocean access combine with a booming tech and manufacturing economy to attract buyers from across the country.', 'Peninsula, Mount Pleasant, West Ashley, Daniel Island, James Island, North Charleston', 'Mount Pleasant, Summerville, Goose Creek', 'Charleston''s historic charm and beach access draw buyers from New York, Charlotte, and Atlanta who are prepared to compete aggressively for the right home — the right agent creates that competition in your favor.', 'Win Charleston listings before buyers from New York and Charlotte find them on Zillow — our platform connects you to motivated Peninsula and Mount Pleasant sellers before any competing agent reaches them.', true)
